<?php
require_once __DIR__.'/../includes/functions.php'; require_role('admin'); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$role=$_POST['role']??'student';$password=$_POST['password']??'';
 if(!$name||!preg_match('/^[a-zA-Z0-9_.-]{3,40}$/',$username)||strlen($password)<8||!in_array($role,['admin','teacher','student'],true)){flash('danger','Check the name, username, role and password (minimum 8 characters).');}
 else {try{$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO users(username,password_hash,role,name,status) VALUES(?,?,?,?,"active")');$q->execute([$username,password_hash($password,PASSWORD_DEFAULT),$role,$name]);$id=(int)$pdo->lastInsertId();
 if($role==='student'){$roll=trim($_POST['roll_number']??'');$dept=trim($_POST['department']??'');$sem=(int)($_POST['semester']??1);$pdo->prepare('INSERT INTO students(user_id,roll_number,department,semester) VALUES(?,?,?,?)')->execute([$id,$roll?:'STU-'.$id,$dept,$sem]);}
 if($role==='teacher'){$pdo->prepare('INSERT INTO teachers(user_id,department) VALUES(?,?)')->execute([$id,trim($_POST['department']??'')]);}
 $pdo->commit();audit('Created '.$role.' account',null,$username,$id);flash('success','Account created successfully.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('danger','Could not create account. Username or roll number may already exist.');}}
 redirect('users.php');
}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['toggle_user'])){verify_csrf();$id=(int)$_POST['toggle_user'];$q=db()->prepare("UPDATE users SET status=IF(status='active','inactive','active') WHERE user_id=? AND user_id<>?");$q->execute([$id,current_user()['user_id']]);audit('Changed user status',null,'user_id='.$id,$id);flash('success','Account status updated.');redirect('users.php');}
$users=db()->query('SELECT u.*,s.roll_number FROM users u LEFT JOIN students s ON s.user_id=u.user_id ORDER BY u.user_id DESC')->fetchAll();
include __DIR__.'/../includes/header.php'; ?>
<div class="row g-3"><div class="col-lg-4"><div class="card"><div class="card-header">Create account</div><div class="card-body"><form method="post"><?= csrf_field() ?><div class="mb-2"><label class="form-label">Full name</label><input class="form-control" name="name" required></div><div class="mb-2"><label class="form-label">Username</label><input class="form-control" name="username" required></div><div class="mb-2"><label class="form-label">Temporary password</label><input class="form-control" type="password" name="password" minlength="8" required></div><div class="mb-2"><label class="form-label">Role</label><select class="form-select" name="role" id="role"><option value="student">Student</option><option value="teacher">Teacher</option><option value="admin">Administrator</option></select></div><div id="studentFields"><div class="mb-2"><label class="form-label">Roll number (optional)</label><input class="form-control" name="roll_number"></div><div class="mb-2"><label class="form-label">Department</label><input class="form-control" name="department"></div><div class="mb-2"><label class="form-label">Semester</label><input class="form-control" type="number" min="1" max="12" name="semester" value="1"></div></div><button class="btn btn-primary w-100 mt-2">Create account</button></form></div></div></div><div class="col-lg-8"><div class="card"><div class="card-header">All accounts</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $x): ?><tr><td><?= e($x['name']) ?><div class="small text-secondary"><?= e($x['roll_number']??'') ?></div></td><td><?= e($x['username']) ?></td><td><span class="badge badge-soft"><?= e($x['role']) ?></span></td><td><?= e($x['status']) ?></td><td><form method="post" class="d-inline"><?=csrf_field()?><button class="btn btn-sm btn-outline-secondary" name="toggle_user" value="<?= $x['user_id'] ?>" data-confirm="Change this account status?">Toggle</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div>
<script>document.getElementById('role').addEventListener('change',e=>document.getElementById('studentFields').style.display=e.target.value==='student'?'block':'none');</script>
<?php include __DIR__.'/../includes/footer.php'; ?>